class Encrypter(keys:CharArray,values:Array<String>,dictionary:Array<String>){private val mapping=HashMap<Char,String>();private val frequency=HashMap<String,Int>();init{for(i in keys.indices)mapping[keys[i]]=values[i];for(word in dictionary){val encrypted=encrypt(word);if(encrypted.isNotEmpty())frequency[encrypted]=(frequency[encrypted]?:0)+1}}fun encrypt(word1:String):String{val result=StringBuilder();for(ch in word1){val value=mapping[ch]?:return "";result.append(value)};return result.toString()}fun decrypt(word2:String)=frequency[word2]?:0}
